const appointment = $json;
const invoiceId = `{{CLINIC_PREFIX}}-INV-${Date.now()}`;
const dueDate = new Date();
dueDate.setDate(dueDate.getDate() + {{INVOICE_DUE_DAYS}});

// Calculate invoice total based on services
let invoiceTotal = parseFloat({{DEFAULT_SERVICE_PRICE}}) || 0;
if (appointment['Service Type']) {
  // Add logic for different service pricing
  const serviceType = appointment['Service Type'].toLowerCase();
  if (serviceType.includes('surgery')) invoiceTotal += 200;
  if (serviceType.includes('dental')) invoiceTotal += 150;
  if (serviceType.includes('emergency')) invoiceTotal += 100;
}

// Generate invoice HTML
const invoiceHtml = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { text-align: center; border-bottom: 2px solid #{{CLINIC_COLOR}}; padding-bottom: 20px; }
    .invoice-details { margin: 20px 0; }
    .services { border: 1px solid #ddd; margin: 20px 0; }
    .services th, .services td { padding: 10px; text-align: left; border-bottom: 1px solid #ddd; }
    .total { font-size: 18px; font-weight: bold; color: #{{CLINIC_COLOR}}; }
    .pay-button { background: #{{CLINIC_COLOR}}; color: white; padding: 15px 30px; text-decoration: none; border-radius: 5px; display: inline-block; margin: 20px 0; }
  </style>
</head>
<body>
  <div class="header">
    <h1>{{CLINIC_NAME}}</h1>
    <p>{{CLINIC_ADDRESS}}</p>
    <p>📞 {{BUSINESS_PHONE_NUMBER}} | 📧 {{BUSINESS_EMAIL}}</p>
  </div>

  <div class="invoice-details">
    <h2>Invoice #${invoiceId}</h2>
    <p><strong>Date:</strong> ${new Date().toLocaleDateString()}</p>
    <p><strong>Due Date:</strong> ${dueDate.toLocaleDateString()}</p>
    <hr>
    <p><strong>Bill To:</strong></p>
    <p>${appointment['Customer Name'] || 'N/A'}</p>
    <p>📧 ${appointment['Customer Email'] || 'N/A'}</p>
    <p>📞 ${appointment['Customer Phone'] || 'N/A'}</p>
    <p><strong>Pet:</strong> ${appointment['Pet Name'] || 'N/A'}</p>
  </div>

  <table class="services" width="100%">
    <tr style="background: #f5f5f5;">
      <th>Service Description</th>
      <th>Date</th>
      <th>Amount</th>
    </tr>
    <tr>
      <td>${appointment['Service'] || 'Veterinary Services'}<br><small>${appointment['Notes'] || 'Standard consultation and treatment'}</small></td>
      <td>${appointment['Date'] || new Date().toLocaleDateString()}</td>
      <td class="total">$${invoiceTotal.toFixed(2)}</td>
    </tr>
    <tr style="background: #f9f9f9;">
      <td colspan="2" style="text-align: right; font-weight: bold;">Total Amount Due:</td>
      <td class="total">$${invoiceTotal.toFixed(2)}</td>
    </tr>
  </table>

  <div style="text-align: center;">
    <a href="{{PAYMENT_GATEWAY_URL}}/pay?invoiceId=${invoiceId}&amount=${invoiceTotal}&email=${encodeURIComponent(appointment['Customer Email'] || '')}" class="pay-button">💳 Pay Now - $${invoiceTotal.toFixed(2)}</a>
  </div>

  <div style="margin-top: 30px; padding: 15px; background: #f0f8ff; border-radius: 5px;">
    <p><strong>Payment Terms:</strong> Payment is due within {{INVOICE_DUE_DAYS}} days of invoice date.</p>
    <p><strong>Late Fee:</strong> {{LATE_FEE_POLICY}}</p>
    <p><strong>Questions?</strong> Contact us at {{BUSINESS_PHONE_NUMBER}} or {{BUSINESS_EMAIL}}</p>
  </div>

  <div style="text-align: center; margin-top: 20px; color: #666; font-size: 12px;">
    <p>Thank you for choosing {{CLINIC_NAME}} for your pet's care! 🐾</p>
  </div>
</body>
</html>
`;

return {
  json: {
    ...appointment,
    invoiceId: invoiceId,
    invoiceTotal: invoiceTotal,
    dueDate: dueDate.toISOString(),
    dueDateFormatted: dueDate.toLocaleDateString(),
    invoiceHtml: invoiceHtml,
    paymentUrl: `{{PAYMENT_GATEWAY_URL}}/pay?invoiceId=${invoiceId}&amount=${invoiceTotal}&email=${encodeURIComponent(appointment['Customer Email'] || '')}`,
    status: 'Invoiced',
    invoiceDate: new Date().toISOString()
  }
};

