const today = new Date();
const overdueInvoices = [];

$input.all().forEach(item => {
  const invoice = item.json;

  // Skip if already paid
  if (invoice.Status === 'Paid') return;

  // Check if due date has passed
  const dueDate = new Date(invoice['Due Date']);
  if (dueDate < today) {
    // Calculate days overdue
    const daysOverdue = Math.floor((today - dueDate) / (1000 * 60 * 60 * 24));

    // Only send reminders for specific intervals (3, 7, 14, 30 days overdue)
    if ([3, 7, 14, 30].includes(daysOverdue)) {
      overdueInvoices.push({
        json: {
          ...invoice,
          daysOverdue: daysOverdue,
          urgencyLevel: daysOverdue >= 30 ? 'URGENT' : daysOverdue >= 14 ? 'HIGH' : 'MODERATE'
        }
      });
    }
  }
});

return overdueInvoices;

